import type LedringAnimation from "../lib/LedringAnimation";
import type { Frame } from "../lib/LedringAnimation";
export type HomeyStartEvent = {
    args: {
        animationId: string;
        args?: Record<string, unknown>;
    };
    return: void;
};
export type HomeyStopEvent = {
    args: {
        animationId: string;
        args?: Record<string, unknown>;
    };
    return: void;
};
export type HomeyFinishEvent = {
    args: {
        animationId: string;
        args?: Record<string, unknown>;
    };
    return: void;
};
export type SDKStartEvent = {
    args: string;
    return: void;
};
export type SDKStopEvent = {
    args: string;
    return: void;
};
export type UpdateFramesEvent = {
    args: {
        animationId: string;
        frames: Array<Frame>;
    };
    return: void;
};
export type FnEvent = {
    args: {
        animationId: string;
        method: string;
        args: unknown;
    };
    return: unknown;
};
export type RegisterAnimationEvent = {
    args: LedringAnimation;
    return: string;
};
export type UnregisterAnimationEvent = {
    args: string;
    return: void;
};
export type RegisterScreensaverEvent = {
    args: {
        name: string;
        animationId?: string;
    };
    return: void;
};
export type UnregisterScreensaverEvent = {
    args: {
        name: string;
        animationId?: string;
    };
    return: void;
};
export type HomeyLedringEvents = {
    start: HomeyStartEvent;
    stop: HomeyStopEvent;
    finish: HomeyFinishEvent;
};
export type SDKLedringEvents = {
    start: SDKStartEvent;
    stop: SDKStopEvent;
    updateFrames: UpdateFramesEvent;
    fn: FnEvent;
    registerAnimation: RegisterAnimationEvent;
    unregisterAnimation: UnregisterAnimationEvent;
    registerScreensaver: RegisterScreensaverEvent;
    unregisterScreensaver: UnregisterScreensaverEvent;
};
